package com.unitepaintball.app;
import java.net.URI;
public final class SharedFeaturePolicy {
 private SharedFeaturePolicy(){}
 public static boolean ownUrl(String url,String base){try{URI u=new URI(url),b=new URI(base);return "https".equalsIgnoreCase(u.getScheme())&&b.getHost().equalsIgnoreCase(u.getHost())&&u.getPort()==b.getPort()&&u.getUserInfo()==null;}catch(Exception e){return false;}}
 public static String path(String value){if(value==null||!value.startsWith("/")||value.startsWith("//")||value.indexOf('\\')>=0||value.contains("\r")||value.contains("\n"))return "/fonctionnalites";try{URI u=new URI(value);return u.getHost()==null&&!u.isAbsolute()?value:"/fonctionnalites";}catch(Exception e){return "/fonctionnalites";}}
 public static String[] mimeTypes(String[] raw){java.util.LinkedHashSet<String> out=new java.util.LinkedHashSet<>();if(raw!=null)for(String value:raw){if(value==null)continue;for(String item:value.split(",")){String t=item.trim().toLowerCase(java.util.Locale.ROOT);if(".json".equals(t))t="application/json";else if(".pdf".equals(t))t="application/pdf";else if(".jpg".equals(t)||".jpeg".equals(t))t="image/jpeg";else if(".png".equals(t))t="image/png";if(t.matches("[a-z0-9.+-]+/([a-z0-9.+-]+|\\*)"))out.add(t);}}return out.toArray(new String[0]);}
 public static String pageForApi(String endpoint){String p=endpoint.split("\\?",2)[0];switch(p){case "/api/admin-gamification":return "/admin/gamification";case "/api/arena":return "/admin/arena";case "/api/admin-dashboard":return "/admin/statistiques";case "/api/admin-settings":return "/admin/parametres";case "/api/admins":return "/admin/administrateurs";case "/api/safety":return "/admin/securite";case "/api/content":return "/admin/publications";case "/api/management":return "/admin/gestion";case "/api/commercial":return "/admin/commercial";case "/api/admin-audit":return "/admin/historique";default:return "/fonctionnalites";}}
 public static String pageForSection(String section){switch(section){case "Réservations":case "Nouvelle réservation":return "/reservations";case "Points":return "/progression";case "Arena":return "/arena";case "Messages":return "/messages-app";case "Galerie":return "/galerie";case "Joueurs":return "/amis";case "Profil":return "/profil";case "Admin":return "/admin";case "Gestion admin":return "/fonctionnalites";case "Finance admin":return "/admin/comptabilite";case "Stocks":return "/admin/stocks";case "Incidents":return "/admin/securite";case "Notifications":return "/notifications";case "Adhésions":return "/adhesions";case "Live":return "/parties";case "Tournois":return "/mon-espace/tournois";case "Groupes":return "/groupes";case "Scénarios":return "/jeux";case "Parties ouvertes":return "/parties";case "Documents":return "/mon-espace";case "Paramètres":return "/parametres";default:return "/fonctionnalites";}}
}
